import React from "react";
import { graphql, type HeadFC } from "gatsby";
import { GatsbyImage, getImage, type IGatsbyImageData } from "gatsby-plugin-image";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/Layout";
import { Post, Company } from "../interfaces";
import data from "../data/data.json";
import { format, isValid, parseISO } from "date-fns";
import { es, fr, enUS, sl } from "date-fns/locale";
import images from "../images";
import AppLink from "../components/AppLink";
import SEO from "../components/seo";
import I18nHeadProvider from "../components/I18nHeadProvider";
import type {
  I18nPageContext,
  LocaleQueryData,
} from "../components/I18nHeadProvider";
import {
  buildBreadcrumbListSchema,
  buildItemListSchema,
  localizeSitePath,
} from "../utils/structuredData";
import {
  getAvailableYears,
  getCategoryServicePath,
  getPostTimestamp,
  getUniqueTaxonomyValues,
  sortPostsByDate,
} from "../utils/postTaxonomy";
import { trackCtaClick } from "../utils/analytics";

const info: Company = data[0];

type Props = {
  data: {
    allPostsJson: {
      nodes: Post[];
    };
    allFile?: {
      nodes: Array<{
        name: string;
        childImageSharp?: {
          gatsbyImageData: IGatsbyImageData;
        } | null;
      }>;
    };
  };
};

type BlogHeadData = LocaleQueryData & Props["data"];

const PostPage: React.FC<Props> = ({ data }) => {
  const posts = data.allPostsJson.nodes;

  const { t, i18n } = useTranslation("blog");
  const [searchTerm, setSearchTerm] = React.useState("");
  const [yearFilter, setYearFilter] = React.useState("all");
  const [categoryFilter, setCategoryFilter] = React.useState("all");
  const [seriesFilter, setSeriesFilter] = React.useState("all");
  const getLocale = (language: string) => {
    switch (language) {
      case "es":
        return es;
      case "fr":
        return fr;
      default:
        return enUS;
    }
  };

  const sortedPosts = React.useMemo(
    () => sortPostsByDate(posts),
    [posts]
  );

  const availableYears = React.useMemo(
    () => getAvailableYears(sortedPosts),
    [sortedPosts]
  );
  const availableCategories = React.useMemo(
    () => getUniqueTaxonomyValues(sortedPosts, "category"),
    [sortedPosts]
  );
  const availableSeries = React.useMemo(
    () => getUniqueTaxonomyValues(sortedPosts, "series"),
    [sortedPosts]
  );
  const imageLookup = React.useMemo(() => {
    return new Map(
      (data.allFile?.nodes || [])
        .map((node) => {
          const image = node.childImageSharp?.gatsbyImageData
            ? getImage(node.childImageSharp.gatsbyImageData)
            : undefined;

          return image ? [node.name, image] : null;
        })
        .filter(
          (
            entry
          ): entry is [string, IGatsbyImageData] => Array.isArray(entry)
        )
    );
  }, [data.allFile?.nodes]);
  const categorySummaries = React.useMemo(
    () =>
      availableCategories.map((category) => ({
        category,
        count: sortedPosts.filter((post) => post.category === category).length,
        servicePath: getCategoryServicePath({ category }),
      })),
    [availableCategories, sortedPosts]
  );

  const normalizedQuery = searchTerm.trim().toLowerCase();

  const filteredPosts = React.useMemo(() => {
    return sortedPosts.filter((post) => {
      const postTime = getPostTimestamp(post.date);
      const postYear =
        postTime === null ? null : new Date(postTime).getFullYear().toString();
      if (yearFilter !== "all") {
        if (postYear === null || postYear !== yearFilter) {
          return false;
        }
      }

      if (categoryFilter !== "all" && post.category !== categoryFilter) {
        return false;
      }

      if (seriesFilter !== "all" && post.series !== seriesFilter) {
        return false;
      }

      if (!normalizedQuery) {
        return true;
      }

      const translatedTitle = t(`blog.${post.slug}-title`, {
        defaultValue: post.title,
      });

      return (
        translatedTitle.toLowerCase().includes(normalizedQuery) ||
        post.title.toLowerCase().includes(normalizedQuery) ||
        (post.tags || []).some((tag) => tag.toLowerCase().includes(normalizedQuery))
      );
    });
  }, [
    categoryFilter,
    normalizedQuery,
    seriesFilter,
    sortedPosts,
    t,
    yearFilter,
    i18n.language,
  ]);

  const searchLabel = t("blog.search_label", {
    defaultValue: "Search",
  });
  const searchPlaceholder = t("blog.search_placeholder", {
    defaultValue: "Search posts by title",
  });
  const filterLabel = t("blog.filter_label", {
    defaultValue: "Filter by year",
  });
  const filterAll = t("blog.filter_all", {
    defaultValue: "All years",
  });
  const filterTopicLabel = t("blog.filter_topic_label", {
    defaultValue: "Filter by topic",
  });
  const filterAllTopics = t("blog.filter_topic_all", {
    defaultValue: "All topics",
  });
  const filterSeriesLabel = t("blog.filter_series_label", {
    defaultValue: "Filter by series",
  });
  const filterAllSeries = t("blog.filter_series_all", {
    defaultValue: "All series",
  });
  const noResults = t("blog.no_results", {
    defaultValue: "No posts match your search.",
  });
  const taxonomyTitle = t("blog.taxonomy_title", {
    defaultValue: "Explore by cluster",
  });
  const taxonomySubtitle = t("blog.taxonomy_subtitle", {
    defaultValue: "Browse the blog by topic cluster and jump directly to the related service page.",
  });

  const getCategoryLabel = (category?: string) =>
    category
      ? (t(`blog.taxonomy.categories.${category}`, {
          defaultValue: category,
        }) as string)
      : "";
  const getSeriesLabel = (series?: string) =>
    series
      ? (t(`blog.taxonomy.series.${series}`, {
          defaultValue: series,
        }) as string)
      : "";

  return (
    <Layout data={info}>
      <article className="w-full sm:w-3/4 mx-auto mb-4">
        <h1 className="text-3xl text-center my-4">{t("blog.title")}</h1>
        <section className="mb-6 rounded-2xl border border-secondary/20 bg-darkBg/40 p-4">
          <h2 className="text-xl text-light">{taxonomyTitle}</h2>
          <p className="mt-2 text-sm text-secondary">{taxonomySubtitle}</p>
          <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
            {categorySummaries.map(({ category, count, servicePath }) => (
              <article
                key={category}
                className="rounded-2xl border border-secondary/15 bg-primary/40 p-4"
              >
                <p className="text-xs uppercase tracking-[0.16em] text-secondary">
                  {t("blog.taxonomy_count", {
                    count,
                    defaultValue: `${count} posts`,
                  })}
                </p>
                <h2 className="mt-2 text-lg text-light">
                  {getCategoryLabel(category)}
                </h2>
                <div className="mt-4 flex flex-wrap gap-3">
                  <button
                    className="rounded-full bg-secondary px-4 py-2 text-sm text-light"
                    type="button"
                    onClick={() => setCategoryFilter(category)}
                  >
                    {t("blog.taxonomy_view_cluster", {
                      defaultValue: "View cluster",
                    })}
                  </button>
                  <AppLink
                    to={servicePath}
                    className="rounded-full bg-purplesemilight px-4 py-2 text-sm font-semibold text-dark"
                    onClick={() => {
                      void trackCtaClick({
                        cta_name: `blog_cluster_${category}`,
                        cta_location: "blog_taxonomy",
                        destination: servicePath,
                        destination_type: "internal",
                      });
                    }}
                  >
                    {t("blog.taxonomy_service_cta", {
                      defaultValue: "Related service",
                    })}
                  </AppLink>
                </div>
              </article>
            ))}
          </div>
        </section>
        <div className="flex flex-col sm:flex-row sm:flex-wrap gap-3 mb-4">
          <label className="flex-1 text-sm text-secondary">
            <span className="block mb-1">{searchLabel}</span>
            <input
              className="w-full rounded-lg border-2 border-secondary/40 bg-darkBg/50 px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-secondary/60"
              type="search"
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
              placeholder={searchPlaceholder}
              aria-label={searchLabel}
            />
          </label>
          <label className="sm:w-48 text-sm text-secondary">
            <span className="block mb-1">{filterLabel}</span>
            <select
              className="w-full rounded-lg border-2 border-secondary/40 bg-darkBg/50 px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-secondary/60"
              value={yearFilter}
              onChange={(event) => setYearFilter(event.target.value)}
              aria-label={filterLabel}
            >
              <option value="all">{filterAll}</option>
              {availableYears.map((year) => (
                <option key={year} value={year}>
                  {year}
                </option>
              ))}
            </select>
          </label>
          <label className="sm:w-52 text-sm text-secondary">
            <span className="block mb-1">{filterTopicLabel}</span>
            <select
              className="w-full rounded-lg border-2 border-secondary/40 bg-darkBg/50 px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-secondary/60"
              value={categoryFilter}
              onChange={(event) => setCategoryFilter(event.target.value)}
              aria-label={filterTopicLabel}
            >
              <option value="all">{filterAllTopics}</option>
              {availableCategories.map((category) => (
                <option key={category} value={category}>
                  {getCategoryLabel(category)}
                </option>
              ))}
            </select>
          </label>
          <label className="sm:w-52 text-sm text-secondary">
            <span className="block mb-1">{filterSeriesLabel}</span>
            <select
              className="w-full rounded-lg border-2 border-secondary/40 bg-darkBg/50 px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-secondary/60"
              value={seriesFilter}
              onChange={(event) => setSeriesFilter(event.target.value)}
              aria-label={filterSeriesLabel}
            >
              <option value="all">{filterAllSeries}</option>
              {availableSeries.map((series) => (
                <option key={series} value={series}>
                  {getSeriesLabel(series)}
                </option>
              ))}
            </select>
          </label>
        </div>
        {filteredPosts.length === 0 ? (
          <p className="text-center text-secondary">{noResults}</p>
        ) : (
          <ul className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredPosts.map((post) => (
              <li
                className="text-center border-2 bg-darkBg/50 rounded-lg p-2 flex-1 flex flex-col"
                key={post.slug}
              >
                <AppLink to={`/blog/${post.slug}`}>
                  {(() => {
                    const postImage =
                      images[post.slug as keyof typeof images] ?? images.bg_workflow;
                    const optimizedImage = imageLookup.get(post.slug);

                    return (
                      <>
                        <div className="flex flex-wrap justify-center gap-2 text-xs text-secondary">
                          {post.category ? (
                            <span className="rounded-full border border-secondary/30 px-2 py-1">
                              {getCategoryLabel(post.category)}
                            </span>
                          ) : null}
                          {post.series ? (
                            <span className="rounded-full border border-secondary/30 px-2 py-1">
                              {getSeriesLabel(post.series)}
                            </span>
                          ) : null}
                        </div>
                        <h2 className="mt-3">{t(`blog.${post.slug}-title`)}</h2>
                        <p className="text-sm text-secondary">
                          {(() => {
                            const parsed = parseISO(post.date);
                            return isValid(parsed)
                              ? format(parsed, "MMMM dd, yyyy", {
                                  locale: getLocale(i18n.language),
                                })
                              : post.date;
                          })()}
                        </p>
                        {optimizedImage ? (
                          <GatsbyImage
                            image={optimizedImage}
                            alt={postImage.alt}
                            className="thumbnail mx-auto my-4 overflow-hidden rounded-xl"
                          />
                        ) : (
                          <img
                            className="thumbnail mx-auto my-4"
                            src={postImage.src}
                            alt={postImage.alt}
                            loading="lazy"
                            decoding="async"
                          />
                        )}
                      </>
                    );
                  })()}
                </AppLink>
              </li>
            ))}
          </ul>
        )}
      </article>

    </Layout>
  );
};

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
    allPostsJson(sort: { date: DESC }) {
      nodes {
        title
        slug
        date
        category
        series
        tags
        primaryServicePath
      }
    }
    allFile(
      filter: {
        sourceInstanceName: { eq: "images" }
        relativeDirectory: { eq: "blog" }
      }
    ) {
      nodes {
        name
        childImageSharp {
          gatsbyImageData(
            width: 640
            layout: CONSTRAINED
            placeholder: BLURRED
            formats: [AUTO, WEBP, AVIF]
          )
        }
      }
    }
  }
`;

const BlogIndexHeadContent: React.FC<{ posts: Post[] }> = ({ posts }) => {
  const { t } = useTranslation("blog");
  const { language, defaultLanguage } = useI18next();

  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home", { ns: "translation" }) as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.blog", { ns: "translation" }) as string,
      path: localizeSitePath("/blog/", language, defaultLanguage),
    },
  ]);

  const postItemListSchema = buildItemListSchema(
    info.url,
    posts.map((post) => ({
      name: t(`blog.${post.slug}-title`, {
        defaultValue: post.title,
      }) as string,
      path: localizeSitePath(`/blog/${post.slug}/`, language, defaultLanguage),
    }))
  );

  const additionalSchemas = [breadcrumbSchema, postItemListSchema].filter(
    Boolean
  ) as object[];

  return (
    <SEO
      data={info}
      titleKey="blog.metaTitle"
      descriptionKey="blog.metaDescription"
      pathname="/blog/"
      schemaType="Organization"
      pageSchemaType="Blog"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

export const Head: HeadFC<BlogHeadData, I18nPageContext> = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <BlogIndexHeadContent posts={data.allPostsJson.nodes} />
  </I18nHeadProvider>
);

export default PostPage;
